import{b as e,O as a,g as d,j as r}from"./chunks/framework.DcaUmd3X.js";const g=JSON.parse('{"title":"常见问题与进阶方向","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/faq/index.md","filePath":"性能测试/1.Jmeter/08.常见问题与进阶.md","lastUpdated":1781755252000}'),n={name:"performance/jmeter/faq/index.md"};function o(s,t,l,i,p,c){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="常见问题与进阶方向" tabindex="-1">常见问题与进阶方向 <a class="header-anchor" href="#常见问题与进阶方向" aria-label="Permalink to &quot;常见问题与进阶方向&quot;">​</a></h1><blockquote><p>踩过的坑不白踩——速查表帮你快速定位，进阶方向告诉你下一步学什么。</p></blockquote><h2 id="常见问题速查" tabindex="-1">常见问题速查 <a class="header-anchor" href="#常见问题速查" aria-label="Permalink to &quot;常见问题速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>根因</th><th>解决</th></tr></thead><tbody><tr><td>创建数据报 400 错误</td><td>数据重复（唯一字段冲突）</td><td>用 <code>\${__time()}</code> 或 <code>\${__UUID()}</code> 生成唯一值</td></tr><tr><td>登录成功但后续请求 401</td><td>Token 没提取到或已过期</td><td>检查 JSON Path 是否正确；看察看结果树确认响应里有 token 字段</td></tr><tr><td>压测时 JMeter 卡顿</td><td>开了察看结果树等查看型监听器</td><td><strong>关掉所有查看型监听器</strong>，只保留汇总报告</td></tr><tr><td>响应时间突然飙升</td><td>数据库锁 / 连接池耗尽 / CPU 打满</td><td>检查被压测系统的资源使用情况</td></tr><tr><td>本机压测数据不准</td><td>JMeter 和被测应用抢 CPU / 内存</td><td><strong>JMeter 和被测系统放不同机器</strong></td></tr><tr><td>压测机端口耗尽</td><td>大量 TIME_WAIT 连接</td><td><code>sysctl</code> 调 <code>net.ipv4.ip_local_port_range</code>、开启 <code>tcp_tw_reuse</code></td></tr><tr><td>OutOfMemoryError</td><td>JMeter 堆内存不够</td><td>调大 JVM 堆：<code>export HEAP=&quot;-Xms4g -Xmx4g&quot;</code></td></tr><tr><td>HTML 报告不生成</td><td>输出目录已存在</td><td>删掉旧目录，或加 <code>-f</code> 强制覆盖</td></tr><tr><td>聚合报告和 HTML 报告百分位不一致</td><td>两种报告的百分位算法不同</td><td>在 <code>user.properties</code> 中设 <code>backend_metrics_percentile_estimator=R_3</code></td></tr><tr><td>CSV 数据每个线程读到同一行</td><td>共享模式设错了</td><td>CSV 数据文件设置 → 共享模式选&quot;所有线程&quot;</td></tr><tr><td>分布式压测结果差异大</td><td>Agent 机器配置不一致</td><td>所有 Agent 用相同配置的机器</td></tr></tbody></table><h2 id="调试检查清单" tabindex="-1">调试检查清单 <a class="header-anchor" href="#调试检查清单" aria-label="Permalink to &quot;调试检查清单&quot;">​</a></h2><p>压测脚本出问题时，按这个顺序排查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 线程数改成 1、循环 1 次，单独跑 → 确认单次能通</span></span>
<span class="line"><span>2. 开察看结果树 → 逐个请求检查状态码和响应内容</span></span>
<span class="line"><span>3. 检查 \${变量名} 是否正确引用 → 加 Debug Sampler 看变量当前值</span></span>
<span class="line"><span>4. 确认 JSON Path / 正则提取器表达式 → 在察看结果树里用&quot;测试&quot;按钮验证</span></span>
<span class="line"><span>5. 检查作用域 → 提取器是不是放在了正确的请求下面？</span></span></code></pre></div><h2 id="进阶方向" tabindex="-1">进阶方向 <a class="header-anchor" href="#进阶方向" aria-label="Permalink to &quot;进阶方向&quot;">​</a></h2><p>跑通第一个压测后，可以往这些方向深入：</p><table tabindex="0"><thead><tr><th>方向</th><th>学什么</th><th>什么时候需要</th></tr></thead><tbody><tr><td><strong>分布式压测</strong></td><td>多台 Agent 同时施压，Controller 统一调度</td><td>单机线程数不够打满目标 QPS</td></tr><tr><td><strong>JSR223 + Groovy</strong></td><td>用 Groovy 写自定义逻辑替代 BeanShell</td><td>需要复杂的数据处理、条件判断</td></tr><tr><td><strong>CI/CD 集成</strong></td><td>Jenkins / GitHub Actions 自动跑压测</td><td>每次发版自动验证性能不退化</td></tr><tr><td><strong>Grafana 实时监控</strong></td><td>Backend Listener → InfluxDB → Grafana</td><td>长时间压测想实时看大屏</td></tr><tr><td><strong>混合协议压测</strong></td><td>HTTP + JDBC + WebSocket 组合脚本</td><td>业务链路跨越多个协议</td></tr><tr><td><strong>自定义插件</strong></td><td>Java 写 Sampler / Function 扩展</td><td>JMeter 自带功能满足不了需求</td></tr></tbody></table><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://jmeter.apache.org/usermanual/index.html" target="_blank" rel="noreferrer">Apache JMeter 官方文档</a></td><td>最权威的参考，所有元件都有详细说明</td></tr><tr><td><a href="https://jmeter-plugins.org/" target="_blank" rel="noreferrer">JMeter Plugins Manager</a></td><td>插件生态，Concurrency Thread Group 等都在这里</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一章是工具书性质的收尾：</p><ul><li><strong>11 个常见问题速查</strong>：覆盖 400/401/OOM/端口耗尽等高频踩坑点</li><li><strong>5 步调试清单</strong>：单线程跑通 → 看结果树 → 查变量 → 验证提取器 → 检查作用域</li><li><strong>6 个进阶方向</strong>：分布式 / Groovy / CI/CD / Grafana / 混合协议 / 自定义插件</li></ul><p>教程总共八章，学习路径回顾：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>心法（一）→ 安装（二）→ 实战（三）→ 元件（四）</span></span>
<span class="line"><span>    → 场景（五）→ 指标（六）→ CLI（七）→ 排错与进阶（八）</span></span></code></pre></div><p>遇到问题优先查第八章速查表，忘了元件用法翻第四章，搞不清指标含义看第六章。记住两条心法——<strong>配前定取后断听</strong>、<strong>父管子近优先</strong>——大多数操作就不会踩坑。</p>`,18)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
